import express, { type NextFunction, type Request, type Response } from "express";
import type { OrderService } from "../application/order-service";
import { DomainError } from "../domain/errors";
import type { OrderLine } from "../domain/order";

const STATUS_BY_CODE: Record<DomainError["code"], number> = {
  not_found: 404,
  invalid_input: 400,
  insufficient_stock: 409,
  invalid_transition: 409,
};

function parseLines(body: unknown): OrderLine[] {
  const items = (body as { items?: unknown } | null)?.items;
  if (!Array.isArray(items)) {
    throw new DomainError("invalid_input", "Body must contain an items array");
  }
  return items.map((item: unknown) => {
    const { productId, quantity } = (item ?? {}) as { productId?: unknown; quantity?: unknown };
    if (typeof productId !== "string" || typeof quantity !== "number") {
      throw new DomainError("invalid_input", "Each item needs productId (string) and quantity (number)");
    }
    return { productId, quantity };
  });
}

export function createApp(service: OrderService): express.Express {
  const app = express();
  app.use(express.json());

  app.post("/orders", (req, res) => {
    res.status(201).json(service.placeOrder(parseLines(req.body)));
  });

  app.get("/orders", (req, res) => {
    const state = typeof req.query.state === "string" ? req.query.state : undefined;
    res.json(service.listOrders(state));
  });

  app.get("/orders/:id", (req, res) => {
    res.json(service.getOrder(req.params.id));
  });

  app.post("/orders/:id/advance", (req, res) => {
    res.json(service.advance(req.params.id));
  });

  app.post("/orders/:id/cancel", (req, res) => {
    res.json(service.cancel(req.params.id));
  });

  app.get("/stock", (_req, res) => {
    res.json(service.stockLevels());
  });

  app.get("/stock/:productId", (req, res) => {
    res.json(service.stockLevel(req.params.productId));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof DomainError) {
      res.status(STATUS_BY_CODE[err.code]).json({ error: err.code, message: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "invalid_input", message: "Malformed JSON" });
    } else {
      res.status(500).json({ error: "internal", message: "Internal server error" });
    }
  });

  return app;
}

